import json
from pathlib import Path
p=Path(__file__).parent
da=json.loads((p/'source-the-aeneid.da.json').read_text())
en=json.loads((p/'source-the-aeneid.json').read_text())
da.update(title='Æneiden',author='Vergil',estimatedTime='~8–10 timer',openingChapterLabel='Bog I — Våben og manden',openingText=(p/'01.draft').read_text().split('\n§\n')[1].split('\n\n')[0])
en.update(estimatedTime='~8–10 hours',openingText=json.loads((p/'candidate-the-aeneid-modern-en.json').read_text())['chapters'][0]['paragraphs'][1])
da['about']='Æneas flygter fra det faldne Troja med sin familie, sine husguder og en flok overlevende. På rejsen mod Italien møder han Dido, der er ved at bygge Karthago. Gudernes krav om at fortsætte rejsen stiller ham over for både hendes kærlighed og sit eget ansvar for folket. I underverdenen viser hans far Anchises ham en fremtid, der rækker helt frem til Rom. Da trojanerne når Latium, bliver deres håb om et hjem en trussel mod mennesker, der allerede bor der.\n\nVergil skrev Æneiden på latin i de sidste årtier af det første århundrede f.Kr., under Augustus. Digtets tolv bøger tager Homers rejser og krige op i en fortælling om Roms mytiske forhistorie. Æneas grundlægger den slægt og den bosættelse, som traditionen lader Rom udspringe af. Selve grundlæggelsen af Rom ligger flere generationer senere.\n\nDenne danske version følger det latinske digt i moderne frie vers. Boginddelingen og tekstafsnittene følger samlingens historiske engelske oversættelse af John Dryden fra 1697. Hver bog begynder derfor med Drydens korte handlingsreferat, tydeligt mærket som hans indledning. Digtet kan både læses for sin store fortælling og for de øjeblikke, hvor en enkelt persons tab standser fremmarchen mod den lovede fremtid.'
en['about']='Aeneas escapes the fall of Troy with his family, his household gods, and a group of survivors. On the journey toward Italy he meets Dido, who is building Carthage. The gods demand that he continue, bringing his obligations to his people into conflict with her love and his own attachments. In the underworld, his father Anchises shows him a future reaching forward to Rome. When the Trojans arrive in Latium, their hope for a home threatens people who already live there.\n\nVirgil wrote the twelve books of the Aeneid in Latin during the final decades of the first century BCE, under Augustus. Its voyages and battles engage closely with Homer and place the story in Rome’s mythical prehistory. Aeneas establishes the settlement and line from which Roman tradition traces its origins. The founding of Rome itself belongs to later generations.\n\nThe historical English text here is John Dryden’s 1697 translation. Each book opens with his prose summary of its events. The modern English keeps that edition’s structure and much of its rhetorical character, with specific corrections documented separately. Read for the sweep of the story and for the moments when an individual loss interrupts the advance toward the promised future.'
da['angleCards']=[dict(title='Skæbnens pris',text='Guderne lover en stor fremtid. Læg mærke til, hvem der skal betale for den, og hvem der selv får lov at vælge.',angleObjective='Jeg vil undersøge forholdet mellem skæbne, valg og ansvar i Æneas’ rejse.'),dict(title='Didos perspektiv',text='Dido har allerede mistet sit hjem og skabt en ny by. Hendes historie spejler Æneas’ og viser, hvad hans afrejse betyder for andre.',angleObjective='Jeg vil følge Didos stemme og undersøge, hvordan fortællingen giver plads til hendes håb og vrede.'),dict(title='Samtalen med Homer',text='Rejserne i første halvdel minder om Odysseen, kampene i anden halvdel om Iliaden. Genkendelige scener får nye følger i Vergils fortælling.',angleObjective='Jeg vil se, hvordan Vergil omformer Homers helte, rejser og kampe.'),dict(title='Pligt og vrede',text='Pietas rummer ansvar for guder, familie og fællesskab. Følg, hvordan den pligt møder sorg, kærlighed og hævntørst.',angleObjective='Jeg vil læse Æneas’ handlinger med blik for både hans pligtfølelse og hans vrede.')]
en['angleCards']=[dict(title='The price of destiny',text='The gods promise a great future. Notice who pays for it and who gets to choose.',angleObjective='I want to examine fate, choice, and responsibility in Aeneas’s journey.'),dict(title='Dido’s perspective',text='Dido has already lost a home and built a new city. Her story parallels Aeneas’s and reveals what his departure means for others.',angleObjective='I want to follow Dido’s voice and consider the space the poem gives her hopes and anger.'),dict(title='The conversation with Homer',text='The journeys in the first half recall the Odyssey, and the battles in the second recall the Iliad. Familiar scenes acquire new consequences.',angleObjective='I want to see how Virgil reshapes Homer’s heroes, journeys, and battles.'),dict(title='Duty and anger',text='Pietas encompasses obligations to gods, family, and community. Follow its encounters with grief, love, and revenge.',angleObjective='I want to read Aeneas’s actions with attention to both his sense of duty and his anger.')]
da['cast']=[dict(name='Æneas',role='Trojanernes fører',description='Søn af Venus og Anchises, far til Ascanius og overlevende fra Trojas fald. Han bærer ansvaret for at føre sit folk til et nyt hjem. Hans pligtfølelse prøves af både tab og vrede.'),dict(name='Dido',role='Karthagos dronning',description='Efter mordet på sin mand er hun flygtet fra Tyros og har grundlagt Karthago. Hun tager gæstfrit imod trojanerne. Forholdet til Æneas bliver afgørende for hendes liv og byens mytiske forhold til Rom.'),dict(name='Turnus',role='Rutulernes fører',description='En ung italisk kriger og bejler til Lavinia. Amata støtter hans ønske om ægteskab, mens varslerne peger mod en udenlandsk svigersøn. Han leder modstanden mod Æneas og forbindes både med mod, stolthed og ødelæggende vrede.'),dict(name='Juno',role='Gudernes dronning',description='Hun hader trojanerne og frygter for sit elskede Karthagos fremtid. Hun rejser stormen og driver krigen i Italien frem. Hendes forhandling med Jupiter får betydning for det folk, der skal opstå af konflikten.'),dict(name='Venus',role='Æneas’ mor',description='Kærlighedens gudinde beskytter sin søn, går i forbøn for ham og får Vulcan til at smede hans våben. Hendes hjælp former også andre menneskers liv.'),dict(name='Anchises',role='Æneas’ far',description='Æneas bærer ham ud af Troja. Han dør på rejsen, men møder sønnen igen i underverdenen og viser ham de fremtidige romerske slægter.')]
en['cast']=[dict(name='Aeneas',role='Leader of the Trojans',description='Son of Venus and Anchises, father of Ascanius, and a survivor of Troy’s fall. He bears responsibility for bringing his people to a new home. Loss and anger repeatedly test his sense of duty.'),dict(name='Dido',role='Queen of Carthage',description='After her husband’s murder she fled Tyre and founded Carthage. She welcomes the Trojans. Her relationship with Aeneas becomes decisive for her life and for the mythical relationship between Carthage and Rome.'),dict(name='Turnus',role='Leader of the Rutulians',description='A young Italian warrior and suitor of Lavinia. Amata favors their marriage, while omens point toward a foreign husband. He leads resistance to Aeneas and embodies courage, pride, and destructive anger.'),dict(name='Juno',role='Queen of the gods',description='She hates the Trojans and fears for the future of her beloved Carthage. She provokes the storm and drives the war in Italy. Her negotiation with Jupiter helps shape the people who will emerge from the conflict.'),dict(name='Venus',role='Aeneas’s mother',description='The goddess of love protects her son, pleads on his behalf, and persuades Vulcan to forge his weapons. Her interventions also shape other people’s lives.'),dict(name='Anchises',role='Aeneas’s father',description='Aeneas carries him out of Troy. He dies on the journey but meets his son again in the underworld and shows him the future Roman generations.')]
da['acclaim']=[];en['acclaim']=[]
da['whyItMatters']=[dict(title='Et hjem har en pris',body='Flygtningene fra Troja søger sikkerhed, men deres ankomst til Italien udløser en ny krig. Digtet forbinder hjemlængsel med erobring og gør plads til både de nyankomne og dem, der forsvarer deres land.'),dict(title='De døde får navne',body='Midt i de store slag standser fortællingen ved forældre, børn og tabte hjem. Pallas, Lausus og Camilla får hver deres historie. Læg mærke til, hvordan sådanne liv ændrer din oplevelse af en sejr.'),dict(title='En slutning at diskutere',body='Digtet slutter, da Æneas dræber Turnus. Her mødes erindringen om Pallas, ønsket om hævn og muligheden for at standse. Slutningen lader læseren overveje forholdet mellem den lovede fred og den handling, der afslutter krigen.')]
en['whyItMatters']=[dict(title='The cost of a home',body='Troy’s refugees seek safety, but their arrival in Italy brings a new war. The poem connects the longing for a home with conquest and gives attention to both newcomers and those defending their land.'),dict(title='The dead have names',body='Amid great battles, the narrative pauses over parents, children, and lost homes. Pallas, Lausus, and Camilla each receive a distinct story. Notice how these lives change the meaning of victory.'),dict(title='An ending to discuss',body='The poem ends when Aeneas kills Turnus. Memory of Pallas, the desire for revenge, and the possibility of restraint meet in that moment. The ending leaves the reader to consider the relationship between the promised peace and the act that ends the war.')]
for lang,x in [('da.',da),('',en)]: (p/f'candidate-the-aeneid.{lang}json').write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
print('two guides written')
